// Decode once: repeated fruits reuse the same MemoryImage cache key.
final Map<String, Uint8List> _fruitArtworkBytes = {
  for (final entry in _fruitArtworkBase64.entries)
    entry.key: base64Decode(entry.value),
};

Uint8List fruitArtworkBytes(String fruit) =>
    _fruitArtworkBytes[fruit] ?? _fruitArtworkBytes['watermelon']!;

